SELECT vp.id, COALESCE(NULLIF(uvp.custom_name, ''), vp.name) AS name, vp.provider_voice_id, vp.avatar_url, vp.gender, vp.age_group, vp.status, vp.sort_no, vp.created_at, vp.updated_at FROM ts_user_voice_profile uvp INNER JOIN ts_voice_profile vp ON vp.id = uvp.voice_profile_id WHERE uvp.user_id = #{query.userId} AND vp.status != 0
AND uvp.status = #{query.status}
AND uvp.status != 0
AND ( COALESCE(NULLIF(uvp.custom_name, ''), vp.name) LIKE CONCAT('%', #{query.keyword}, '%') OR vp.name LIKE CONCAT('%', #{query.keyword}, '%') )
AND vp.gender = #{query.gender}
AND vp.age_group = #{query.ageGroup}
ORDER BY uvp.updated_at DESC, uvp.id DESC

SELECT *
FROM ts_user_voice_profile
WHERE user_id = #{userId}
  AND voice_profile_id = #{voiceProfileId}
  AND status != 0
LIMIT 1
